const { computeWaves } = require('./work-waves.cjs');

// Folder names that only group work documents; their items are shown directly under the parent.
const WRAPPER_FOLDERS = new Set(['stories', 'tasks']);

const linkedDocId = (item) => (item.type === 'doc' ? item.id : item.link?.type === 'doc' ? item.link.id : null);

// Tidies autogenerated sidebars:
// - a folder's own index page is used as the category link instead of a child item;
// - `stories/` and `tasks/` wrapper categories are flattened;
// - Epic/Story/Task items carry a status class (see custom.css);
// - Epics are ordered by delivery wave, matching the Epics index.
async function sidebarItemsGenerator({ defaultSidebarItemsGenerator, ...args }) {
  const items = await defaultSidebarItemsGenerator(args);
  const docsById = new Map(args.docs.map((doc) => [doc.id, doc]));
  const frontMatterOf = (item) => docsById.get(linkedDocId(item))?.frontMatter || {};
  const indexId = `${args.item.dirName}/index`;

  const tidy = (list) => list.flatMap((item) => {
    if (item.type === 'doc' && item.id === indexId) return [];
    if (item.type !== 'category') return [withStatus(item)];
    if (!item.link && WRAPPER_FOLDERS.has(item.label)) return tidy(item.items);
    return [withStatus({ ...item, items: tidy(item.items) })];
  });

  const withStatus = (item) => {
    const { work_type: workType, status } = frontMatterOf(item);
    if (!workType || !status) return item;
    const className = [item.className, 'sidebar-work-item', `sidebar-status--${status}`].filter(Boolean).join(' ');
    return { ...item, className };
  };

  const result = tidy(items);
  if (args.item.dirName !== 'epics') return result;

  const epics = result.map((item) => {
    const frontMatter = frontMatterOf(item);
    return { item, id: frontMatter.work_id, dependsOn: frontMatter.depends_on || [], title: frontMatter.title || '' };
  });
  const waves = computeWaves(epics.filter((epic) => epic.id));
  const waveOf = (epic) => waves.get(epic.id) || Number.MAX_SAFE_INTEGER;
  return epics
    .sort((a, b) => (waveOf(a) - waveOf(b)) || a.title.localeCompare(b.title))
    .map(({ item }) => item);
}

module.exports = { sidebarItemsGenerator };
